import React, { useState } from "react";
import { useEffect } from "react";
import { useParams } from "react-router-dom";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import IGASolutionList from "src/views/pages/ITSolutionDetails/ITSolutionOverview/IGASolutionList";
import IGASolutionOptions from "src/views/pages/ITSolutionDetails/ITSolutionOverview/IGASolutionOptions/IGASolutionOptions";
import PlanSection from "src/views/pages/ITSolutionDetails/ITSolutionOverview/PlanSection";
import StreamlineIdentity from "src/views/pages/ITSolutionDetails/ITSolutionOverview/StreamlineIdentity";
import { toastError, toastSuccess } from "src/utils/utils";
import { use } from "i18next";
import { Box } from "@mui/material";
import bgImg from "../../../assets/images/section1BgImg.png";
import bgImgSmall from "../../../assets/images/bannerSectionBgImgSmall.png";
import "../../../styles/animation.css";

const ITSolutionOverviewPage = () => {
  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
  }, []);

  const [homeOverviewData, setHomeOverviewData] = useState({});
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();
  const [backgroundPositionY, setBackgroundPositionY] = useState(0);
  //animation
  useEffect(() => {
    const handleScroll = () => {
      const offset = window.pageYOffset || document.documentElement.scrollTop;
      setBackgroundPositionY(offset); // Set the background position directly based on scroll offset
    };

    window.addEventListener("scroll", handleScroll);
    handleScroll(); // Initialize position

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  const fetchOverviewMainTitle = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_HOME.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setHomeOverviewData(responseData[0]);
        } else {
          setHomeOverviewData({});
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchOverviewMainTitle();
  }, [id]);

  return (
    <>
      <Box
        sx={{
          position: "relative",
          minHeight: "100vh",
          overflowX: "hidden",
          overflowY: "auto",
          scrollBehavior: "smooth",
          transition: "2s ease-in-out",
        }}
      >
        <Box
          sx={{
            backgroundImage: { xs: `url(${bgImgSmall})`, sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `right ${backgroundPositionY}px`,
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            zIndex: -1,
            pointerEvents: "none",
            transition: "background-position 1.5s ease-in-out",
          }}
        />
        <StreamlineIdentity
          loading={loading}
          homeOverviewData={homeOverviewData}
        />
        <IGASolutionOptions homeOverviewData={homeOverviewData} />
        <IGASolutionList homeOverviewData={homeOverviewData} />
        <PlanSection homeOverviewData={homeOverviewData} />
      </Box>
    </>
  );
};

export default ITSolutionOverviewPage;
