import {
  Box,
  Container,
  Grid,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  Table,
  Button,
  styled,
} from "@mui/material";
import React, { useEffect, useState } from "react";
import screenImg from "../../../../assets/images/screenImg.png";
import CancelOutlinedIcon from "@mui/icons-material/CancelOutlined";
import TaskAltOutlinedIcon from "@mui/icons-material/TaskAltOutlined";
import ScrollAnimation from "react-animate-on-scroll";
import { Link, useParams } from "react-router-dom";
import { axiosInstance } from "src/network/adapter";
import { API_BASE_URL, ApiEndpoints } from "src/network/endpoints";
import { toastError } from "src/utils/utils";
import FallbackSpinner from "src/@core/components/spinner";

// const features = [
//   "Built-in report library and custom reports",
//   "Rule-based account creation and modification templates",
//   "Multi-approval workflow",
//   "OU and group-based delegation",
//   "Automated stale account cleanup",
//   "Time-bound access management    ",
//   "Customizable dashboard",
// ];

const IGASolutionList = ({ homeOverviewData }) => {
  const CustomTableCell = styled(TableCell)(({ theme }) => ({
    fontSize: "16px",
    [theme.breakpoints.down("sm")]: {
      fontSize: "14px",
    },
    [theme.breakpoints.up("md")]: {
      fontSize: "16px",
    },
    [theme.breakpoints.up("lg")]: {
      fontSize: "18px",
    },
    fontWeight: 600,
    lineHeight: "20px",
    textTransform: "none",
    color: "#667085",
    wordBreak: "break-word",
    whiteSpace: "normal",
  }));
  const HeaderTableCell = styled(TableCell)(({ theme }) => ({
    fontSize: "17px",
    [theme.breakpoints.down("sm")]: {
      fontSize: "14px",
    },

    textTransform: "none",
    color: "#667085",
    fontWeight: 600,
    lineHeight: "20px",
    textWrap: "wrap",
  }));
  const [overviewFeatures, setOverviewFeatures] = useState([]);
  const [overviewFeaturesTitle, setOverviewFeaturesTitle] = useState({});
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();

  const fetchOverviewFeatures = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_FEATURES.list(itSolutionId))
      .then((response) => {
        setOverviewFeatures(response.data.data);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchOverviewFeaturesTitle = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_FEATURES_TITLE.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        responseData.map((item) => {
          setOverviewFeaturesTitle(item);
        });
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchOverviewFeatures();
    fetchOverviewFeaturesTitle();
  }, [id]);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{ px: { xs: 5, sm: 10, lg: 15, xl: 20 } }}
        >
          <Grid container rowGap={{ xs: 5, sm: 8, md: 12 }}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                flexDirection: "column",
                gap: 3,
              }}
            >
              <ScrollAnimation
                animateIn="fade-in-up-whoweare"
                animateOut="fade-out-down-whoweare"
              >
                <Typography
                  sx={{
                    fontSize: {
                      xs: "26px",

                      md: "28px",
                      lg: "38px",
                    },
                    fontWeight: 500,
                    lineHeight: { xs: "34px", md: "54px", lg: "70px" },
                    color: "#201D28",
                    textAlign: "center",
                    textWrap: "wrap",
                  }}
                >
                  {/* An enterprise IGA solution for your hybrid Active Directory
                  environment */}
                  {homeOverviewData?.title_3}
                </Typography>
              </ScrollAnimation>
              <ScrollAnimation
                animateIn="fade-in-up-whoweare"
                animateOut="fade-out-down-whoweare"
              >
                {" "}
                <Typography
                  sx={{
                    fontSize: { xs: "14px", sm: "18px" },
                    fontWeight: 500,
                    lineHeight: { xs: "26px", sm: "30px" },
                    color: "#646271",
                    textAlign: "center",
                    px: { lg: 15, xl: 20 },
                    textWrap: "wrap",
                  }}
                >
                  {/* ADManager Plus supports hybrid AD management and reporting,
                  risk assessment, identity life cycle management, workflow
                  orchestration, and integration with various enterprise
                  applications to manage, govern, and secure enterprise
                  identities. */}

                  <div
                    dangerouslySetInnerHTML={{
                      __html: homeOverviewData?.description_3
                        ? `<style>p { margin: 0; }</style>${homeOverviewData?.description_3}`
                        : "", // Fallback to an empty string if description_1 is undefined
                    }}
                  />
                </Typography>
              </ScrollAnimation>
            </Grid>
            {overviewFeatures.length > 0 && (
              <Grid
                item
                container
                rowSpacing={{ xs: 5, md: 0 }}
                columnSpacing={5}
              >
                <Grid item xs={12} md={8.5}>
                  <TableContainer
                    sx={{ border: "2px solid #EAECF0", borderRadius: "9px" }}
                  >
                    <Table aria-label="simple table">
                      <TableHead
                        sx={{
                          bgcolor: "#F9FAFB",
                        }}
                      >
                        <TableRow>
                          <HeaderTableCell>
                            {overviewFeaturesTitle?.title_1}
                          </HeaderTableCell>
                          <HeaderTableCell align="center">
                            {overviewFeaturesTitle?.title_2}
                          </HeaderTableCell>
                          <HeaderTableCell align="center">
                            {overviewFeaturesTitle?.title_3}
                          </HeaderTableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {overviewFeatures?.map((item, index) => (
                          <TableRow
                            key={index}
                            sx={{
                              "&:last-child td, &:last-child th": { border: 0 },
                            }}
                          >
                            <CustomTableCell component="th" scope="row">
                              {item.feature}
                            </CustomTableCell>
                            {overviewFeaturesTitle?.title_2 && (
                              <TableCell align="center">
                                {item.is_native_tools === true ? (
                                  <TaskAltOutlinedIcon
                                    sx={{ color: "#19DAC7", fontSize: "30px" }}
                                  />
                                ) : (
                                  <CancelOutlinedIcon
                                    sx={{ color: "#D03030", fontSize: "30px" }}
                                  />
                                )}
                              </TableCell>
                            )}
                            {overviewFeaturesTitle?.title_3 && (
                              <TableCell align="center">
                                {item.is_plus === true ? (
                                  <TaskAltOutlinedIcon
                                    sx={{ color: "#19DAC7", fontSize: "30px" }}
                                  />
                                ) : (
                                  <CancelOutlinedIcon
                                    sx={{ color: "#D03030", fontSize: "30px" }}
                                  />
                                )}
                              </TableCell>
                            )}
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                </Grid>
                <Grid item xs={12} md={3.5}>
                  <Box
                    sx={{
                      border: "1px solid #C8C8C8",
                      borderRadius: "12px",
                      display: "flex",
                      flexDirection: "column",
                      justifyContent: "center",
                      alignItems: "center",
                      gap: 5,
                      px: 5,
                      height: "100%",
                      py: { xs: 5, md: 2 },
                    }}
                  >
                    <ScrollAnimation animateIn="zoom-in-out">
                      <Box>
                        <img src={screenImg} />
                      </Box>
                    </ScrollAnimation>
                    <ScrollAnimation
                      animateIn="fade-in-up-whoweare "
                      animateOut="fade-out-down-whoweare"
                    >
                      <Typography
                        gutterBottom
                        sx={{
                          fontSize: { xs: "14px", sm: "18px" },
                          lineHeight: { xs: "26px", sm: "30px" },
                          fontWeight: 500,
                          color: "#646271",
                          textAlign: "center",
                        }}
                      >
                        {/* Fully functioning installation of ADManager Plus. Try your
                      hands on the product now. */}
                        <div
                          dangerouslySetInnerHTML={{
                            __html: `<style>p { margin: 0; }</style>${homeOverviewData?.online_demo_description}`,
                          }}
                        />
                      </Typography>
                    </ScrollAnimation>
                    <ScrollAnimation
                      animateIn="fade-in-up-whoweare "
                      animateOut="fade-out-down-whoweare"
                    >
                      <Box>
                        <Link to={`/it-solution-demo/${id}`}>
                          <Button
                            variant="contained"
                            sx={{
                              fontSize: { xs: "14px", md: "16px" },
                              fontWeight: 600,
                              borderRadius: "16px",
                              padding: "3px 24px",
                              textDecoration: "none",
                            }}
                          >
                            Online Demo
                          </Button>
                        </Link>
                      </Box>
                    </ScrollAnimation>
                  </Box>
                </Grid>
              </Grid>
            )}
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default IGASolutionList;
